// ============================================================
//  MH-QUANTUM-INSPECTOR v2.1 — Bundle Builder
//  node scripts/build-bundle.js
//  Output: mhq.bundle.js (browser-ready, zero deps)
// ============================================================

"use strict";

const fs   = require("fs");
const path = require("path");

const ROOT = path.join(__dirname, "..");
const OUT  = path.join(ROOT, "mhq.bundle.js");

const FILES = [
  "mh-quantum.config.js",
  "analyzer/stacking-context-resolver.js",
  "analyzer/computed-style-extractor.js",
  "analyzer/dom-crawler.js",
  "core/temporal-observer.js",
  "core/dimension-sampler.js",
  "renderer/webgl-context.js",
  "renderer/quantum-mesh-builder.js",
  "renderer/hud-overlay.js",
  "transport/e2e-cipher.js",
  "transport/payload-schema.js",
  "transport/ws-client.js",
  "ui/toast.js",
  "ui/control-panel.js",
  "core/quantum-engine.js",
];

function build() {
  const missing = FILES.filter((relPath) => !fs.existsSync(path.join(ROOT, relPath)));
  if (missing.length) {
    console.error("Missing bundle inputs:");
    missing.forEach((file) => console.error(`  - ${file}`));
    process.exit(1);
  }

  const banner = `/*!
 * MH-QUANTUM-INSPECTOR v2.1 — BUNDLE
 * Built from ${FILES.length} browser modules.
 * Generated by scripts/build-bundle.js
 */`;

  const parts = [banner, ""];
  let totalBytes = 0;

  FILES.forEach((relPath) => {
    const fullPath = path.join(ROOT, relPath);
    const src = fs.readFileSync(fullPath, "utf8");
    totalBytes += Buffer.byteLength(src, "utf8");
    parts.push(`// ${"─".repeat(60)}`);
    parts.push(`// MODULE: ${relPath}`);
    parts.push(`// ${"─".repeat(60)}`);
    parts.push(src.trimEnd());
    parts.push("");
  });

  const bundle = parts.join("\n");
  fs.writeFileSync(OUT, bundle, "utf8");

  const bundleKB = (Buffer.byteLength(bundle, "utf8") / 1024).toFixed(1);
  const sourceKB = (totalBytes / 1024).toFixed(1);
  console.log(`Built mhq.bundle.js (${bundleKB} KB, source ${sourceKB} KB)`);
}

build();
